const payload = $json.body ?? $json;
const rawText = String(payload.text ?? payload.message ?? payload.body ?? '').trim();
const userId = String(payload.user_id ?? payload.userId ?? '').trim();
const externalId = String(payload.external_id ?? payload.externalId ?? payload.id ?? `n8n-${Date.now()}`).trim();

function todaySaoPaulo() {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());
}

function normalizeDate(text, fallback) {
  const iso = text.match(/\b(20\d{2}-\d{2}-\d{2})\b/);
  if (iso) return iso[1];

  const br = text.match(/\b(\d{1,2})\/(\d{1,2})\/(20\d{2})\b/);
  if (br) {
    const [, day, month, year] = br;
    return `${year}-${month.padStart(2, '0')}-${day.padStart(2, '0')}`;
  }

  return fallback;
}

function normalizeAmount(text) {
  const match = text.match(/(?:r\$\s*)?(\d{1,3}(?:\.\d{3})*|\d+)(?:,(\d{1,2})|\.(\d{1,2}))?/i);
  if (!match) return 0;

  const integer = match[1].replace(/\./g, '');
  const cents = match[2] ?? match[3] ?? '00';
  return Number(`${integer}.${cents.padEnd(2, '0')}`);
}

function normalizeType(text, explicitType) {
  const normalizedExplicit = String(explicitType ?? '').toLowerCase();
  if (['income', 'receita', 'entrada'].includes(normalizedExplicit)) return 'income';
  if (['expense', 'despesa', 'saida', 'saída'].includes(normalizedExplicit)) return 'expense';

  const lower = text.toLowerCase();
  if (/\b(recebi|receita|sal[aá]rio|entrada|ganhei|pix recebido|reembolso)\b/.test(lower)) {
    return 'income';
  }

  return 'expense';
}

function buildDescription(text) {
  const withoutAmount = text
    .replace(/(?:r\$\s*)?\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?/ig, '')
    .replace(/\b(20\d{2}-\d{2}-\d{2})\b/g, '')
    .replace(/\b\d{1,2}\/\d{1,2}\/20\d{2}\b/g, '')
    .replace(/\b(gastei|paguei|comprei|recebi|receita|despesa|entrada|saida|saída)\b/ig, '')
    .replace(/\s+/g, ' ')
    .trim();

  return withoutAmount || text.slice(0, 120) || 'Lancamento via n8n';
}

const transactionDate = normalizeDate(rawText, todaySaoPaulo());
const amount = normalizeAmount(rawText);
const type = normalizeType(rawText, payload.type);
const description = String(payload.description ?? buildDescription(rawText)).slice(0, 255);
const competenceMonth = `${transactionDate.slice(0, 7)}-01`;
const errors = [];

if (!userId) errors.push('Informe user_id no corpo da requisicao.');
if (!rawText) errors.push('Informe text com a mensagem financeira.');
if (!amount || Number.isNaN(amount)) errors.push('Nao consegui identificar o valor da transacao.');

return [{
  json: {
    valid: errors.length === 0,
    error: errors.join(' '),
    raw: payload,
    message_log: {
      user_id: userId || null,
      channel: payload.channel ?? 'whatsapp',
      direction: 'in',
      raw_text: rawText,
      parsed_json: {
        type,
        amount,
        description,
        transaction_date: transactionDate,
        competence_month: competenceMonth,
      },
      external_id: externalId,
    },
    transaction: {
      user_id: userId,
      type,
      amount,
      description,
      notes: rawText,
      transaction_date: transactionDate,
      competence_month: competenceMonth,
      source: 'n8n',
      external_message_id: externalId,
      origin_type: 'manual',
      status: 'active',
    },
  },
}];

return [{
  json: {
    ok: true,
    message: 'Lancamento criado pelo n8n.',
    parsed: $('Normalizar mensagem').item.json.transaction,
    supabase: $json,
  },
}];

return [{
  json: {
    ok: false,
    message: $('Normalizar mensagem').item.json.error,
    example: {
      user_id: 'uuid-do-usuario',
      text: 'gastei R$ 35,90 no mercado hoje',
      external_id: 'msg-001',
    },
  },
}];
